INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (1, 'home', '/', 'Expert Physiotherapists', '', '<div class="row">\n                <div class="col-lg-4 col-md-4 col-sm-4 col-xs-12">\n                    <span class="text-block time-block">  \n                                <span class="time-text"><i class="fa fa-clock-o"></i> Mon to Sun: <strong>8.30am - 8.30pm</strong></span>\n                    </span>\n                </div>\n                <div class="col-lg-5 col-md-5 col-sm-5  col-xs-12">\n                    <div class="top-text">\n                        <ul class="nav-li">\n                            <li><i class="fa fa-phone"></i><a href="tel:+918595321652"> +91 85953 21652</a></li>\n                            <li><i class="fa fa-envelope-o"></i> info@krphysiotherapy.com</li>\n                        </ul>\n                    </div>\n                </div>\n        \n                <div class="col-lg-3 col-md-3 col-sm-3  col-xs-12">\n                    <div class="top-text">\n                         <ul class="nav-li">\n                            <li><a href="https://www.facebook.com/krphysiotherapynoida/" target="_blank"><i class="fa fa-facebook"> </i></a></li>\n                            <li><a href="https://twitter.com/Kr_physio" target="_blank"> <i class="fa fa-twitter"></i></a></li>\n                            <li><a href="https://www.linkedin.com/in/neelam-sharma-085915105/" target="_blank"> <i class="fa fa-linkedin"></i></a></li>\n                            <li><a href="https://www.instagram.com/krphysiotherapy_clinic/" target="_blank"> <i class="fa fa-instagram"></i></a></li>\n                        </ul>\n                        \n                    </div>\n                </div>\n            </div>', 'home', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (2, 'about', '/about.html', 'About KR Physiotherapy & Rehabilitation Clinic', 'Noida Sector 51’s trusted centre for non-surgical pain relief, neurological recovery, sports rehab and physiotherapy at home. Open 7 days, 8:30am – 8:30pm.', '<h2>Welcome to KR Physiotherapy &amp; Rehabilitation Clinic</h2>\n<p><strong>Physiotherapist &middot; Physiotherapy at Home &middot; Physiotherapy Clinic in Noida</strong></p>\n<p>Physiotherapy — more popularly known as medical therapy — helps patients rehabilitate from disease, injury, disability and chronic pain. Our physiotherapists have a deep understanding of how the body works and help patients recover from pain, injury, paralysis, ligament injury and neurological conditions, treating both chronic pain and acute problems.</p>\n\n<h2>Best Physiotherapy Service in Noida</h2>\n<p><strong>KR Physiotherapy &amp; Rehabilitation Clinic</strong> provides the best physiotherapy service in Noida. Our physiotherapists are highly qualified, and the clinic focuses on maintaining health for people of all ages — helping patients manage pain and prevent disease.</p>\n<p>This treatment is very effective, but only when the practising physiotherapist has proper experience. The therapist must know how to assess and how to treat. A physiotherapist knows very well how each body part works — and if a body part stops working, they know how to restore it. That is why proper assessment, knowledge and experience matter so much.</p>\n\n<h2>Led by Dr. Neelam Sharma &amp; Team</h2>\n<p><strong>Dr. Neelam Sharma</strong> and her team work for the welfare of patients suffering from orthopaedic problems, chronic pain conditions, sports injuries, neurological problems, women’s health issues and geriatric conditions.</p>\n<p>In a country where most people suffer from arthritis, diabetes and lifestyle-related pain conditions, physiotherapy is a ray of hope. Our effort is to treat patients <strong>without surgery</strong> — therapy that acts like medicine, yet is cheaper, safer and more beneficial than drugs, with <strong>no side effects</strong>.</p>\n<p>If a loved one at home is suffering from a condition that limits their life, contact the best physiotherapist in Noida — KR Physiotherapy &amp; Rehabilitation Clinic.</p>\n\n<h2>Our Mission</h2>\n<p>KR Physiotherapy &amp; Rehabilitation Clinic aims to optimise the work and well-being of every patient, so they can return to their chosen lifestyle activities — at home, at work and at leisure.</p>\n\n<h2>What We Do</h2>\n<p>Our patients deserve the absolute best in assessment, diagnosis and treatment. A major part of our treatment focus is to give you real, easy-to-understand explanations of your problem and a treatment plan that leads to full recovery.</p>\n\n<h2>Services &amp; Amenities</h2>\n<ul>\n<li>Latest &amp; advanced physiotherapy equipment</li>\n<li>Advanced manual therapy</li>\n<li>Free parking available</li>\n<li>Clinic located near Sector-34 Metro station</li>\n<li>ATM and bank in the same building</li>\n<li>On-call therapist available for home visits in special medical cases</li>\n<li>Home physiotherapy service across Noida for conventional treatment</li>\n</ul>\n\n<h2>Visit Us</h2>\n<p>Kisan Tower, Basement, Main Road, Hosiyarpur, Sector-51, Noida, Uttar Pradesh 201301<br/>Phone: <a href="tel:+918595321652">+91 85953 21652</a>, <a href="tel:+917668527335">+91 76685 27335</a><br/>Email: <a href="mailto:info@krphysiotherapy.com">info@krphysiotherapy.com</a><br/>Hours: Monday to Sunday, 8:30am – 8:30pm</p>', 'about', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (3, 'services', '/services.html', 'Physiotherapy Services in Noida – KR Physiotherapy & Rehabilitation Clinic', 'Eight specialised clinical departments — musculoskeletal, neurological, sports, geriatric, paediatric, chronic pain, women’s health and physiotherapy at home — delivered by MIAP-certified therapists in Sector 51, Noida.', '<p>KR Physiotherapy &amp; Rehabilitation Clinic provides the best physiotherapy service in Noida across eight specialised departments: musculoskeletal, neurological, sports, geriatric and paediatric physiotherapy, chronic pain rehabilitation, women’s health physiotherapy, and physiotherapy at home. Every treatment plan begins with a thorough biomechanical assessment and follows internationally validated, evidence-based protocols — non-surgical, medication-free and tailored to each patient.</p>', 'services', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (4, 'treatments', '/treatments.html', 'Physiotherapy Treatment in Noida', 'Non-surgical, evidence-based treatment for back pain, neck pain, knee pain, ligament injuries, sciatica, cerebral palsy, scoliosis and Bell’s palsy — assessed first, treated second, at our Sector 51 clinic or your home.', '<p>KR Physiotherapy &amp; Rehabilitation Clinic treats the full range of musculoskeletal and neurological conditions without surgery: back pain and sciatica, shoulder pain, knee pain, neck pain, knee ligament injuries, hijama cupping therapy, cerebral palsy, scoliosis and Bell’s palsy. Our physiotherapists assess the root cause first, then combine manual therapy, dry needling, cupping and advanced electrotherapy for lasting relief.</p>', 'treatments', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
