INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (8, 'physiotherapy-in-noida-sector-34', '/physiotherapy-in-noida-sector-34.html', 'Physiotherapy in Noida Sector 34', 'Best Physiotherapy Clinic & Home Care in Noida Sector 34', '<img src="images/back-pain.jpg" alt="Back Pain" class="img-responsive mb30">\n                       <h2>Physiotherapy - Types, Treatment and Procedure</h2>\n                        <p>With the help of physiotherapy one can restore mobility and normalcy in their life after affected by an injury, disease or disability. A physiotherapy session includes manual therapy, advising and educating the patient. It is helpful for patient of any age to manage further pain and prevent subsequent injuries or diseases.</p>\n                        <p>Physiotherapy clinics in Noida sector 34 adopt a more holistic approach to a patient\'s treatment process by taking into consideration their lifestyle and other dimensions.</p>\n                        <h2>Types Of Physiotherapy Treatments</h2>\n                        <ul>\n                        <li><strong>Neurological:</strong> It is given when there is a loss of balance and coordination, weakness of the muscles, loss of function, muscle spasms, and decrease in sensation. The aim is to establish mobility of the body part and to treat the functional disorders.</li>\n                        <li><strong>Orthopedic:</strong> The aim of this is to treat diseases related to the musculoskeletal system, including correcting the muscles, bones, ligaments, joints, and tendons.</li>\n                        <li><strong>Post-Surgical Rehabilitation:</strong> This therapy is given to patients recovering after an operation. The main aim is to restore strength, mobility and confidence through progressive, guided exercise.</li>\n                        <li><strong>Pediatric:</strong> It is done to improve the acute injuries found in children in the time of birth involving certain genetic defects or delay in physical growth.</li>\n                        <li><strong>Geriatric:</strong> In this, age-related matters are treated such as osteoporosis and arthritis.</li>\n                        <li><strong>Vestibular rehabilitation:</strong> The main focus of this is to bring back the balance of the body which is caused by a problem in the inner ear.</li>\n                        </ul>\n                        <h2>How Is Physiotherapy Done?</h2>\n                        <p>Best physiotherapists in sector 34 Noida uses a variety of techniques, resolute by the nature of the injury sustained and particular problem that is being treated. The common one of them is:</p>\n                        <ul>\n                        <li><strong>Manual manipulation:</strong> Moving the soft tissues and the joints better circulation flushes excess fluids from the body.</li>\n                        <li><strong>Electrical stimulation of the nerves:</strong> Delivering electric currents in controlled intensity helps to contain the pain signals.</li>\n                        <li><strong>Acupuncture:</strong> This is a great way of stimulating the CNS.</li>\n                        <li><strong>Demonstration:</strong> Demonstrating proper movement patterns help patients to recover on their own.</li>\n                        </ul>\n                        <h2>Who needs physiotherapy?</h2>\n                        <p>Persons suffering from following conditions:</p>\n                        <ul>\n                        <li>Injured while playing</li>\n                        <li>Suffering with chronic pain</li>\n                        <li>During and after pregnancy</li>\n                        <li>During and after surgery</li>\n                        <li>Recover comfortably during and after pregnancy</li>\n                        <li>Prevent from thrombosis</li>\n                        <li>Prevent from pressure sores</li>\n                        <li>Prevent muscle wasting and joint mobility</li>\n                        </ul>', 'location', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (9, 'physiotherapy-in-noida-sector-35', '/physiotherapy-in-noida-sector-35.html', 'Physiotherapy in Noida Sector 35', 'Best Physiotherapy Clinic & Home Care in Noida Sector 35', '<h2>Techniques of Physiotherapy</h2>\n                        <img src="images/back-pain.jpg" alt="Back Pain" class="img-responsive mb30">\n                       \n                        <p>Physiotherapy uses different treatments and applies preventative approaches as per the specific problems you are experiencing.</p>\n                        <p>First visit is for assessment to help determine what help you might need.  The main approaches physiotherapists in sector 35 Noida may use are:</p>\n                        <ul>\n                            <li>Education and advice</li>\n	                        <li>Movement and exercise</li>\n                            <li>Manual therapy</li>\n                        </ul>\n                        <p>Sometimes other techniques may also be tried.</p>\n\n                        <h2>Education and Advice</h2>\n                        <p>The main aspect of physiotherapy is looking at the body as a whole and not focusing on the individual factors of an injury.</p>\n                        <p>Thus, providing general advice about ways to improve wellbeing – such as, by taking regular exercise and maintaining a healthy weight– is an important part of treatment.</p>\n                        <p>A physiotherapist also gives specific advice for everyday activities and reduces risk of pain or injury.For example, for back pain, you may be given advice about good posture, lifting or carrying techniques, and avoiding twisting, over-stretching or prolonged standing.</p>\n                        \n                        <h2>Movement and Exercise</h2>\n                        <p>Physiotherapists usually recommend movement and exercise for improving your mobility and function. This may include:</p>\n                        <ul>\n                           <li>Exercises to improve movement and strength– these need to be repeated regularly for a set length of time.</li>\n	                       <li>Activities involving moving whole body, such as walking or swimming for recovering from an operation or injury.</li>\n                           <li>Exercises carried out in warm, shallow water; the water help relax and support the muscles and joints.</li>\n                           <li>Advice and exercises to help you increase or maintain your physical activity.</li>\n                           <li>Providing mobility aids</li>\n                        </ul>\n                        \n                        <h2>Manual Therapy</h2>\n                        <p>Manual therapy is a technique where a physiotherapist uses their hands for manipulating, mobilizing and massaging the body tissues for:</p>\n                        <ul>\n                        <li>Relieving pain and stiffness</li>\n                        <li>Improving blood circulation</li>\n                        <li>Helping fluid drain more efficiently from body parts</li>\n                        <li>Improving the movement of different body parts</li>\n                        <li>Promoting relaxation</li>\n                        </ul>\n                        <p>Manual therapy treats specific problems, such as back pain and a range of conditions that don\'t affect the bones, joints or muscles.</p>\n\n                        <h2>Other Techniques</h2>\n                        <p>Other techniques used by best physiotherapy clinics in Noida sector 35 to help ease pain and promote healing include:</p>\n                        <ul>\n                            <li><strong>Acupuncture – </strong>where fine needles are inserted into specific points, with the aim of reducing pain</li>\n                            <li><strong>Transcutaneous Electrical Nerve Stimulation (TENS) –</strong> A small, battery-operated device is used to deliver an electric current for relieving pain</li>\n                            <li><strong>Ultrasound –</strong> Where high-frequency sound waves are used to treat deep tissue injuries</li>\n                        </ul>\n                        <p>Some people have found these treatments effective, but there isn\'t much scientific evidence.</p>', 'location', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (10, 'physiotherapy-in-noida-sector-52', '/physiotherapy-in-noida-sector-52.html', 'Physiotherapy in Noida Sector 52', 'Best Physiotherapy Clinic & Home Care in Noida Sector 52', '<h2>Physiotherapist in a Rehabilitation Team</h2>\n                        <img src="images/back-pain.jpg" alt="Back Pain" class="img-responsive mb30">\n                       \n                        <p>Physiotherapy is governed internationally by World Physiotherapy, this shows that the profession is responsible for achieving the profession’s scope of practice and defining the roles of physiotherapists in sector 52 Noida, with National Physiotherapy Associations. Physiotherapy is an autonomous profession and it can be operated as members of health service provider or rehabilitation teams or as independent practitioners.</p>\n                        <h2>Where Physiotherapists Work</h2>\n                        <p>Physiotherapists work in a wide range of public, private and voluntary sector settings;</p>\n                         <ul>\n                         <li><strong>Hospitals:</strong> In outpatients, on medical and surgical wards and in specialized units;</li>\n                         <li><strong>Community and Primary Care Health Centers:</strong> In health centers or visiting people in their homes, assessing and treating a wide variety of muscle, joint and ligament problems and women’s health, neurological and orthopaedic conditions and many more;</li>\n                         <li><strong>Schools:</strong> Helping children achieve their full potential;</li>\n                         <li><strong>Workplace:</strong> Providing assessments, pre-employment screening, risk management and educating workers in correct techniques;</li>\n                         <li><strong>Private Practice:</strong> Assessing and treating a wide variety of muscle, joint and ligament problems and many more.</li>\n                         </ul>\n                                                 \n                        <h2>Knowledge and Skills</h2>\n                        <p>After professional training, best physiotherapy clinics in Noida sector 52 should have the knowledge, skills and judgment to provide services for musculoskeletal and orthopedic function, neurological, muscular, skeletal, postural and vestibular function, and prescription of assistive devices to optimize function.</p>\n                        <p>Physiotherapists use their professional knowledge and practical skills, together with thinking skills and skills for interaction to identify what is limiting an individual’s movement.</p>\n                        \n                        <h2>Assessment and Identification</h2>\n                        <p>The examination with actual or potential impairments, activity limitations, or participation restrictions by using specific tests and measures. Physiotherapists are required to:</p>\n                        <ul>\n                            <li>Undertake a comprehensive assessment of the patient</li>\n                            <li>Evaluate the findings from the assessment to make clinical judgments</li>\n                            <li>Implement a physical therapist treatment program and education in agreement</li>\n                            <li>Evaluate and re-evaluate the outcomes of any treatments</li>\n                            <li>Make recommendations for self-management</li>\n                            <li>Collaborate with health professionals and other key stakeholders</li>\n                            <li>Formulate a diagnosis</li>\n                            <li>Provide consultation within their expertise</li>\n                        </ul>\n                       <h2>Intervention and Treatment</h2>\n                       <p>Intervention and treatment is aimed to prevent impairments, activity limitations, participatory restrictions, disability and injury. The physiotherapist determines the interventions and manages the needs of the individual as per the examination, evaluation, diagnosis, plan, goals and outcomes of the planned interventions. Intervention is implemented and modified to reach agreed goals and interventions may include:</p>\n                       <ul>\n                          <li>Education</li>\n                          <li>Therapeutic Exercise</li>\n                          <li>Functional training</li>\n                          <li>Manual therapy techniques</li>\n                          <li>Prescription, application, and fabrication of devices/equipment</li>\n                          <li>Electrotherapeutic modalities</li>\n                          <li>Physical agents and mechanical modalities</li>\n                      </ul>', 'location', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (11, 'physiotherapy-in-noida-sector-53', '/physiotherapy-in-noida-sector-53.html', 'Physiotherapy in Noida Sector 53', 'Best Physiotherapy Clinic & Home Care in Noida Sector 53', '<img src="images/back-pain.jpg" alt="Back Pain" class="img-responsive mb30">\n                        <h2>Vital Role Played By Physiotherapy</h2>\n                        <p>The pandemic has challenged all aspects of our profession, in hospitals, rehab settings, private clinics and in the community. As we have progressed towards the new normal of pandemic life, here we will see the essential role of physiotherapy and its future.</p>\n                        <p>Physiotherapists in sector 53 Noida assesses, diagnose and treat conditions that are might there from the time of birth or acquired. Physiotherapists assess the movement and function and work together with the clients and other health professionals to optimize functional outcomes.</p>\n                        <h2>Essential Services</h2>\n                        <p>Pandemic was a year where healthcare workers were on the front lines to fight against the virus. Physiotherapists were asked to provide essential care to those patients who require emergency services.</p>\n                        <p>At K R Physiotherapy and other clinics, physiotherapists used personal protective equipment to provide physiotherapy to clients who would physically decline without these services. Therapists were also deployed in hospitals and have changed areas of practices to best serve areas that are in need.</p>\n                        <p>For all of us the life has changed both personally and professionally. Best physiotherapy clinics in Noida sector 53 workers volunteered to go to long term care homes and support personal support workers in vulnerable long term care facilities; from those who have dust off and relearn more about technology and virtual rehab to those that have redefined what teamwork truly means; and to those that have expanded their role of what profession offers.</p>\n                       \n                        <h2>Physiotherapy Helps Lives</h2>\n                        <p>At <strong>KR Physiotherapy</strong>, we continue to provide care to our existing clients and accept new clients’ everyday while attentively following public health and colleague guidelines. We have successfully implemented secure rehabilitation programs and determine our approach to manage new client assessments on an individual basis.</p>\n                        <p>We always work towards opening new branches for our clients according to the public health guidelines in the near future; we continue our commitment to provide the best quality care to all our clients.  Our provided physiotherapy services are an integral part of the health care system and can help restore and maintain an individual’s mobility, function and well being. The health and welfare of our clients continue to be the number one commitment for our <strong>doctor for physiotherapy in sector-53 Noida</strong>.  You can contact us to see how we can best serve and meet priorities and needs during this challenging time.</p>', 'location', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `pages` (`id`, `slug`, `path`, `title`, `subtitle`, `content_html`, `template`, `status`, `created_at`, `updated_at`) VALUES (12, 'physiotherapy-in-noida-sector-71', '/physiotherapy-in-noida-sector-71.html', 'Physiotherapy in Noida Sector 71', 'Best Physiotherapy Clinic & Home Care in Noida Sector 71', '<h2>What Physiotherapists do?</h2>\n                        <img src="images/back-pain.jpg" alt="Back Pain" class="img-responsive mb30">\n                       \n                        <p>Physiotherapy involves the treatment of injury, disease and disorders through any physical methods — such as exercise, massage, manipulation and other treatments.</p>\n                        <p>Becoming a physiotherapist can be incredibly rewarding; in your daily work, you would be helping people who have been injured to recover from and come back to their normal conditions and live more independently. Best physiotherapy clinics in Noida sector 71 treats patients across a wide age range – from young children to the elderly.</p>\n                        <p>Most of the people believe that physiotherapists work mainly with back and sports-related injuries, but that’s not true. Physiotherapists are highly trained professionals who do provide treatment for those suffering from physical problems that can be caused due to injury, disease, illness and ageing. </p>\n                        <p>The main purpose of physiotherapist is to improve a person\'s quality of life with the use of variety of treatments to alleviate pain and restore function or, lessen the effects of any dysfunction.</p>\n                        <h2>Career Development Opportunities</h2>\n                        <p>There are several opportunities to advance your career and many career pathways in the public health system. Some private practitioners expand their practices to offer additional services, such as Pilates classes.</p>\n                        <p>Physiotherapy doctor in sector-71 Noida can complete a course to become a credentialed diabetes educator, and there is also the future possibility that they can prescribe some medications for pain and mobility-related conditions, however, this may take a number of years. It can also happen that critical care physiotherapists will be using techniques such as ultrasound in the future.</p>\n                        <h2>Role Of The Physiotherapist</h2>\n                        <p>The role is varied and rarely is the same. A physiotherapist may assess the physical condition of a patient to diagnose problems and offer a treatment plan, or they can also be re-training patients to walk, or cope with crutches, walking frames, or wheelchairs.\n                        </p><p>Physiotherapists spend much time educating patients to prevent further injuries and to help people lead a healthy lifestyle.</p>\n                        <p>Physiotherapists in sector 71 Noida may also plan and implement community fitness programs. Finally, they can also issue sick leave certificates.</p>\n                        <p>During their career, they treat all manner of people including children, premature babies, pregnant women, people undergoing rehabilitation, athletes, the elderly, and those need help following injuries, strokes, or major surgery.</p>\n                        <h2>Key Duties Of A Physiotherapist</h2>\n                        <p>Physiotherapists use a variety of techniques for those who are affected by injuries caused by illness, disability or ageing.</p>                        \n                        <p>Some of the responsibilities include:</p>\n                        <ul>\n                            <li>Diagnosing and treating various physical problems</li>\n                            <li>Developing treatment programs</li>\n                            <li>Conducting therapeutic exercise sessions</li>\n                            <li>Using specialist techniques </li>\n                            <li>Collecting and analyzing data</li>\n                            <li>Writing reports and case notes</li>\n                            <li>Liaising with other health professionals </li>\n                            <li>Educating and training patients </li>\n                            <li>Keeping up to date with the latest industry knowledge</li>\n                         </ul>', 'location', 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'musculoskeletal-physiotherapy', 'Musculoskeletal Physiotherapy', 'Expert diagnosis and hands-on treatment for joint, muscle, ligament and spinal pain — restoring strength, flexibility and long-term movement without surgery.', '<p>Musculoskeletal physiotherapy treats conditions affecting muscles, joints, bones and soft tissues. If you have been suffering from joint, back or muscle pain, a structured physiotherapy programme provides lasting relief rather than temporary fixes.</p><p><strong>How we help:</strong></p><ul><li>Reduce pain and inflammation</li><li>Restore joint mobility and muscle flexibility</li><li>Rebuild strength with progressive exercise programmes</li><li>Correct posture and movement patterns to prevent recurrence</li><li>Speed up your safe return to work, sport and daily activities</li></ul><p>Every plan begins with a thorough biomechanical assessment, so treatment targets the true root cause of your pain — not just the symptoms.</p>', 'accessibility_new', '/images/services/1.jpg', 1, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (2, 'neurological-physiotherapy', 'Neurological Physiotherapy', 'Specialised rehabilitation for stroke, paralysis, Bell''s palsy and nerve-related conditions — retraining the nervous system to restore movement, balance and independence.', '<p>Neurological physiotherapy addresses conditions of the nervous and neuromuscular systems: stroke (CVA/TIA), spinal cord and traumatic brain injuries, Bell''s palsy, Parkinson''s disease, multiple sclerosis and more.</p><p><strong>Our neuro rehab focus:</strong></p><ul><li>Re-learn sitting balance, standing and walking (gait training)</li><li>Reduce spasticity and improve muscle control</li><li>Retrain facial muscles for Bell''s palsy recovery</li><li>Improve coordination, proprioception and fall prevention</li><li>Support family members with home-care guidance</li></ul><p>People with neurological conditions need higher levels of care and specialised equipment — our Sector 51 centre is fully equipped, and early treatment significantly improves outcomes.</p>', 'psychology', '/images/services/2.jpg', 2, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (3, 'chronic-pain-physiotherapy', 'Chronic Pain Physiotherapy', 'Structured, non-surgical relief for long-standing pain — back, neck, joints and post-injury stiffness — combining advanced electrotherapy, manual therapy and graded exercise.', '<p>Chronic pain physiotherapy helps patients who have lived with pain for months or years — long-standing back and neck pain, persistent joint pain, post-fracture stiffness and pain that has not responded to medication alone.</p><p><strong>How we help:</strong></p><ul><li>Thorough assessment to identify the true driver of your pain</li><li>Advanced electrotherapy and manual therapy to settle symptoms</li><li>Graded exercise programmes to rebuild strength and confidence</li><li>Posture, ergonomics and movement re-education</li><li>Relapse-prevention strategies for long-term self-management</li></ul><p>These protocols are safe, non-surgical and benefit patients of all ages — including those who have been told to simply live with their pain.</p>', 'healing', '/images/services/3.jpg', 3, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (4, 'sports-physiotherapy', 'Sports Physiotherapy', 'Rapid, evidence-based recovery for athletic injuries — sprains, strains, ACL and tendon injuries — plus performance screening and injury-prevention programmes.', '<p>Sports injuries differ from everyday injuries: athletes place extreme demands on muscles, joints and bones. Our sports physiotherapy programme treats muscle strains, ligament sprains (ACL, MCL), tendon problems such as tennis elbow, shin splints, plantar fasciitis and more.</p><p><strong>What we deliver:</strong></p><ul><li>Accurate injury diagnosis and staged return-to-play plans</li><li>Manual therapy, taping and sport-specific exercise rehab</li><li>Strength and conditioning to rebuild performance safely</li><li>Biomechanical screening to prevent re-injury</li></ul><p>Whether you play professionally or at weekends, the goal is the same: a confident, fully-rehabilitated return to your sport.</p>', 'directions_run', '/images/services/4.jpg', 4, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (5, 'geriatric-physiotherapy', 'Geriatric Physiotherapy', 'Gentle, effective care for seniors — arthritis management, balance and fall prevention, post-joint-replacement rehab and mobility preservation for an active later life.', '<p>With age come conditions such as arthritis, osteoporosis, joint replacements, Alzheimer''s and balance disorders. Geriatric physiotherapy reduces pain and keeps older adults mobile, confident and independent.</p><p><strong>Programme highlights:</strong></p><ul><li>Arthritis pain management and joint protection</li><li>Balance training and fall prevention</li><li>Post-operative rehab after hip/knee replacement</li><li>Strength and flexibility maintenance</li><li>Confidence-building so seniors stay active for years</li></ul><p>Physiotherapy is a proven tool for seniors to regain confidence in their physical abilities and continue living life on their own terms.</p>', 'elderly', '/images/services/5.jpg', 5, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (6, 'paediatric-physiotherapy', 'Paediatric Physiotherapy', 'Play-based therapy for infants, children and teens — developmental delays, cerebral palsy, torticollis and childhood injuries, guided by specialist paediatric skills.', '<p>Paediatric physiotherapy supports the physical needs of infants, children and adolescents — from delayed milestones to neurological and orthopaedic conditions.</p><p><strong>We help children who:</strong></p><ul><li>Are late learning to sit, crawl or walk</li><li>W-sit, bottom-shuffle or toe-walk</li><li>Have cerebral palsy or other neuromuscular diagnoses</li><li>Have torticollis, plagiocephaly or post-fracture stiffness</li><li>Have juvenile arthritis or chronic pain conditions</li></ul><p>Movement is essential to learning and growing. Our therapists detect developmental issues early and build play-based programmes that optimise each child''s abilities.</p>', 'child_care', '/images/services/6.jpg', 6, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (7, 'women-health-physiotherapy', 'Women''s Health Physiotherapy', 'Private, specialised care for pregnancy, postnatal recovery and pelvic health — from back pain and core weakness to incontinence and pelvic floor retraining.', '<p>Women''s bodies change significantly through pregnancy, delivery and later life. Our women''s health physiotherapy is delivered in a private, calm environment by therapists who understand these stages.</p><p><strong>We help with:</strong></p><ul><li>Lower back, pelvic and hip pain during and after pregnancy</li><li>Core strengthening and diastasis recti recovery</li><li>Pelvic floor activation and retraining</li><li>Urinary incontinence control</li><li>Postnatal return-to-fitness programmes</li></ul><p>Every programme is tailored to your stage — prenatal, postnatal or beyond — with honest guidance on what is safe at every step.</p>', 'pregnant_woman', '/images/services/7.jpg', 7, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `services` (`id`, `slug`, `name`, `short_description`, `full_description_html`, `icon`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (8, 'physiotherapy-at-home', 'Physiotherapy at Home', 'Bedside physiotherapy across Noida for patients who cannot travel — paralysis, post-surgical recovery, elderly care — with the same clinical standards as the clinic.', '<p>KR Physiotherapy brings clinic-standard treatment to your home anywhere in Noida. Our experienced physiotherapists personally visit, assess your condition and deliver the full treatment plan at your bedside.</p><p><strong>Home visits for:</strong></p><ul><li>Paralysis, stroke and Parkinson''s care</li><li>Post-surgical recovery (knee/hip replacement, spine surgery)</li><li>Bedridden and elderly patients</li><li>Back, neck and knee pain when travel is difficult</li><li>Post-fracture stiffness and neurological conditions</li></ul><p>We understand pain or medical problems can make travel impossible — family members can simply call to book a visit.</p>', 'home_health', '/images/services/8.jpg', 8, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'back-pain', 'Physiotherapy for Back Pain', 'Musculoskeletal Rehabilitation', 'Research suggests 80% of adults experience lower back pain, most often from sedentary lifestyles. Pain may originate from muscle, ligament or nerve — our team identifies the true source and treats it with manual therapy, dry needling and physio modalities.', '<ul><li>Dull ache or sharp pain in the lower, mid or upper back</li><li>Pain radiating from buttock to foot (sciatica) with numbness or burning</li><li>Stiffness after sitting or standing for long periods</li><li>Muscle spasm and reduced flexibility</li><li>Pain that worsens with bending, lifting or poor posture</li></ul>', '<ul><li><strong>Sedentary lifestyle</strong> — prolonged hunched sitting weakens spinal support muscles</li><li><strong>Disc bulge or herniation</strong> — compressing the sciatic nerve</li><li><strong>Poor posture</strong> — wrong lifting technique, bad mattress, slouched workstation</li><li><strong>Pregnancy &amp; postpartum</strong> — hormonal loosening and added load on back muscles</li><li><strong>Arthritis</strong> — osteoarthritis, rheumatoid arthritis, ankylosing spondylitis affecting spinal joints</li></ul>', '<p>Back pain is the most common problem we treat. Pain can originate from muscle, ligament or nerve depending on the underlying cause — which is why accurate assessment comes first. The KR physiotherapy team follows all the manual therapies including mobilisation, chiropractic, dry needling and cupping, and provides treatment by physio modalities as needed.</p><h3>Back pain with sciatica</h3><p>Sciatic nerve compression from a disc bulge or herniation can cause pain from the buttock to the foot along with numbness, weakness or burning. Physiotherapy is the best line of treatment — we use chiropractic, cupping therapy and manual therapy to relieve it.</p><h3>Back pain due to bad posture</h3><p>Prolonged sitting, lifting in the wrong posture and lying on a bad mattress stress back muscles and ligaments. We guide you on correct posture at your workspace and in daily activity to cure and prevent recurrence.</p><h3>Back pain due to pregnancy</h3><p>Hormones during pregnancy weaken muscles and ligaments while the growing bump loads the back. Our female physiotherapist provides specialised postpartum back-pain treatment.</p><h3>Back pain due to arthritis</h3><p>Inflammation of spinal joints — osteoarthritis, rheumatoid arthritis, ankylosing spondylitis, psoriatic arthritis — responds well to ultrasound, TENS, IFT and manual therapy, all available in-clinic. We use single or combined treatment lines based on your rehabilitation programme.</p>', '/images/back-pain.jpg', 1, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (2, 'shoulder-pain', 'Physiotherapy for Shoulder Pain', 'Musculoskeletal Rehabilitation', 'Injury, arthritis, frozen shoulder, strain/sprain or dislocation can all cause shoulder pain. We identify the underlying cause — impingement, frozen shoulder or rotator cuff injury — and treat it with manual therapy and targeted rehabilitation.', '<ul><li>Pain on lifting the arm overhead or behind the back</li><li>Stiffness and reduced range of motion (frozen shoulder)</li><li>Weakness when lifting or rotating the arm</li><li>Pain at night, especially lying on the affected side</li><li>Clicking, catching or instability in the joint</li></ul>', '<ul><li><strong>Impingement</strong> — repetitive overhead movement pinching shoulder tendons</li><li><strong>Frozen shoulder</strong> — progressive stiffening and pain, common after injury or immobilisation</li><li><strong>Rotator cuff injury</strong> — strain or tear of the stabilising tendons</li><li><strong>Arthritis</strong> — wear of the joint cartilage</li><li><strong>Strain/sprain or dislocation</strong> — sports falls and accidents</li></ul>', '<p>Do you have shoulder pain? KR Physiotherapy gives you the best advice and treatment. We assess the underlying cause and treat it directly — any kind of injury, arthritis, frozen shoulder, strain/sprain or dislocation of the shoulder can be helped.</p><h3>Shoulder impingement</h3><p>Repetitive shoulder movement can cause impingement, which responds very well to physiotherapy. We rebuild muscle strength and range of motion so you recover faster.</p><h3>Frozen shoulder</h3><p>One of the most common causes of shoulder pain. We care for many patients with frozen shoulder, using progressive mobilisation and stretching to restore movement.</p><h3>Rotator cuff injury</h3><p>If you are suffering from a rotator cuff injury or tear, physiotherapy is the best route to healing. Our clinic follows all the manual therapies for treating shoulder pain — helping you avoid surgery wherever possible.</p>', '/images/schoulder-pain.jpg', 2, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (3, 'knee-pain', 'Physiotherapy for Knee Pain', 'Musculoskeletal Rehabilitation', 'The knee is the largest and most complex joint in the body. Injury, arthritis, overuse, aging, mechanical problems and medical conditions all cause knee pain — physiotherapy addresses the root cause non-surgically.', '<ul><li>Pain behind or around the kneecap, sometimes travelling to thigh or shin</li><li>Swelling and inflammation around the joint</li><li>Stiffness — difficulty bending or straightening the knee</li><li>Redness and warmth over the joint</li><li>Clicking or popping sounds during movement</li><li>Giving way or inability to bear weight</li></ul>', '<ul><li><strong>Injuries</strong> — ACL injury, fractures, torn meniscus, bursitis, sprains, patellar tendinitis</li><li><strong>Arthritis</strong> — osteoarthritis, rheumatoid arthritis, gout, pseudogout, septic arthritis</li><li><strong>Overuse</strong> — repetitive stress common in runners and cyclists</li><li><strong>Aging</strong> — gradual wear of joint structures and bony growths</li><li><strong>Mechanical problems</strong> — loose bodies, IT band syndrome, dislocated kneecap, foot or hip pain referring to the knee</li></ul>', '<p>The appropriate plan depends on the cause and severity of your knee pain. Common approaches include rest, ice therapy, supportive bracing and — most importantly — structured physiotherapy.</p><h3>How physiotherapy reduces knee pain</h3><p>Physiotherapy is a proven, non-invasive approach that addresses the underlying causes and promotes joint health:</p><ul><li><strong>Pain management</strong> — ice/heat therapy and TENS to control pain and inflammation</li><li><strong>Manual therapy</strong> — hands-on techniques and soft-tissue massage to restore range of motion</li><li><strong>Strengthening exercises</strong> — targeted muscle work around the knee for joint stability</li><li><strong>Patient education</strong> — posture and body mechanics to reduce daily joint stress</li><li><strong>Custom plans and home programmes</strong> — tailored to your specific condition with exercises to continue at home</li></ul><p>We provide the best physiotherapy treatment for knee pain in Noida and nearby areas — call us to book an appointment for any knee-related problem.</p>', '/images/knee-pain.jpg', 3, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (4, 'neck-pain', 'Physiotherapy for Neck Pain', 'Musculoskeletal Rehabilitation', 'Physiotherapy is the most effective treatment for neck pain — eliminating pain and discomfort so you can live freely. We assess the cause: poor posture, sedentary lifestyle, injury or age-related changes.', '<ul><li>Heaviness and pain in the cervical spine and arm</li><li>Headache, dizziness or vertigo</li><li>Pain radiating down the arm, with or without tingling</li><li>Soreness and mild swelling around the neck</li><li>Reduced ability to turn or tilt the head</li></ul>', '<ul><li><strong>Degeneration</strong> — age-related wear of the cervical spine</li><li><strong>Injury</strong> — trauma such as whiplash</li><li><strong>Poor posture</strong> — long sitting hours, overuse of mobile and computer</li><li><strong>Excess weight</strong> — overstressed back and neck muscles</li></ul>', '<p>Neck pain is felt behind the head in the cervical spine and surrounding area, and can combine with headache, dizziness and arm symptoms. Left untreated it can lead to secondary problems — persistent headaches, radiating arm pain and reduced head movement — so early physiotherapy matters.</p><h3>How physiotherapy helps</h3><p>Our physiotherapists strengthen your neck and shoulder muscles so overstress-related pain reduces. Mobilisation, chiropractic, dry needling and electrotherapy (US, SWD, TENS) all play important roles. We first assess you to rule out the possible cause, then plan treatment accordingly — most patients see lasting relief without any medication.</p><h3>When is neck pain serious?</h3><p>If pain does not settle within a few days, or radiates into your arm with numbness, consult a physiotherapist promptly. Our team will assess and treat the root cause before it becomes chronic.</p>', '/images/neck-pain.jpg', 4, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (5, 'knee-ligament-injury', 'Knee Ligament Injuries', 'Sports Rehabilitation', 'Knee ligaments connect thigh bone to lower leg bone. Tears and sprains — most commonly the ACL — cause sudden pain, swelling and instability. Mild and moderate injuries recover fully with structured physiotherapy.', '<ul><li>Pain, often sudden and severe</li><li>A loud pop or snap at the moment of injury</li><li>Rapid swelling after the injury</li><li>A feeling of looseness or instability in the joint</li><li>Inability to put weight on the leg without pain</li></ul>', '<ul><li><strong>ACL injury</strong> — the most commonly injured ligament; sudden direction changes, jumping and landing (skiing, basketball, football)</li><li><strong>PCL injury</strong> — direct blow to the knee, often in car accidents; about 20% of ligament injuries</li><li><strong>MCL injury</strong> — pressure on the outside of the knee, common in football</li><li><strong>LCL injury</strong> — force pushing the knee joint from the inside</li></ul>', '<p>The knee has four main ligaments — ACL, PCL, MCL and LCL — and any can be sprained or torn. In mild and moderate injuries, physiotherapy will help you recover fully: reducing swelling, restoring range of motion, then rebuilding strength and stability with progressive exercise.</p><h3>After surgery</h3><p>In severe cases where the ligament is completely torn, reconstructive surgery may be required — your orthopaedic surgeon decides based on severity. Post-surgery, physiotherapy is essential: we speed your recovery, restore full knee function and get you back to sport and daily life safely.</p>', '/images/knee-ligament-injuries.jpg', 5, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (6, 'hijama-cupping-therapy', 'Hijama Cupping Therapy', 'Manual Therapy', 'Hijama (wet) cupping is a safe, effective procedure with zero side effects that gives immediate relief. Also known as medicinal cupping, it removes toxins and triggers the body''s natural healing response.', '<ul><li>Chronic back, neck, knee or arthritic pain</li><li>Tension headaches and migraine</li><li>Seasonal allergies and sinus trouble</li><li>Bloating, indigestion and constipation</li><li>Fatigue, sluggishness and poor circulation</li></ul>', '<p>Cupping is used when sluggish circulation, toxin build-up and muscle tension keep the body from healing itself. It complements — not replaces — physiotherapy for the conditions above.</p>', '<p>Hijama cupping therapy is very safe and gives immediate relief. Cups create suction on the skin (dry cupping) for 2–3 minutes; for wet cupping, tiny sterile incisions then allow elimination of toxic blood and fluids. Proper sterilisation technique is followed throughout.</p><h3>Types of cupping</h3><ul><li>Hijama / wet cupping</li><li>Dry cupping</li><li>Fire cupping</li><li>Moving / dynamic cupping</li></ul><h3>Benefits</h3><ul><li><strong>Pain relief</strong> — back, neck, knee, arthritic pain, headache and migraine</li><li><strong>Sinus discomfort</strong> — many patients report easier, freer comfort through the day</li><li><strong>Skin health</strong> — increased blood flow keeps skin glowing and toned</li><li><strong>Hair growth</strong> — scalp cupping removes toxins and stimulates follicles</li><li><strong>Digestion</strong> — helps bloating, ulcers and constipation</li><li><strong>Relaxation</strong> — increased circulation relieves deep tension</li></ul><h3>When cupping is not used</h3><ul><li>Fractures, bleeding disorders, haemophilia</li><li>Severe infection or non-compliant patients</li></ul>', '/images/Hijama-Cupping-Therapy.jpg', 6, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (7, 'cerebral-palsy', 'Physiotherapy for Cerebral Palsy', 'Neurological Rehabilitation', 'Cerebral palsy (CP) is a group of neurological disorders appearing in infancy or early childhood that disrupt the brain''s ability to control movement, posture and balance. Physiotherapy maintains and improves a child''s abilities at every stage.', '<ul><li>Delayed milestones — difficulty sitting, standing or walking</li><li>Stiff, tight muscles (spasticity) and awkward movements</li><li>Poor coordination, balance and depth perception</li><li>Slow, writhing or jerky involuntary movements</li><li>Increased reflexes and scissor-like leg movement</li></ul>', '<ul><li>Abnormal brain development during pregnancy, birth or early infancy</li><li>Birth complications and oxygen deprivation</li><li>Neonatal infections such as meningitis</li><li>Genetic factors — in many cases the cause is not clear</li><li>CP is non-progressive: it does not worsen over time</li></ul>', '<p>Cerebral refers to the brain; palsy to loss or impairment of motor function. The four main types are <strong>spastic</strong> (most common — stiffness and awkward movement), <strong>dyskinetic</strong> (involuntary writhing movements), <strong>ataxic</strong> (balance and coordination difficulty) and <strong>mixed</strong>. Physiotherapy is the most important treatment after diagnosis, focusing on function, movement and the child''s abilities.</p><h3>Our physiotherapy programme</h3><ul><li><strong>Passive stretching</strong> — relieves soft-tissue tightness in spastic muscles</li><li><strong>Joint rotation</strong> — neck, shoulder, hip, ankle: reduces stiffness, improves circulation</li><li><strong>Targeted stretching</strong> — calf, quadriceps and hamstrings for toe-walking and stiff knees</li><li><strong>Strengthening</strong> — bridging, cobra position, resistance-band work, dynamic quadriceps, supported squats</li><li><strong>Core stability</strong> — swiss-ball exercises for trunk control</li><li><strong>Balance &amp; coordination</strong> — normal, tandem and sideways walking</li></ul><p>A child can attend school while continuing therapy sessions — programmes are built around daily life.</p>', '/images/Cerebral-Palsy.jpg', 7, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (8, 'scoliosis', 'Physiotherapy for Scoliosis', 'Musculoskeletal Rehabilitation', 'Scoliosis is a sideways curvature of the spine affecting any age — most commonly seen in children during growth spurts. Most cases are mild; physiotherapy strengthens the muscles that support the spine and manages the curve.', '<ul><li>Uneven shoulders — one higher than the other</li><li>One hip higher or more prominent</li><li>One side of the rib cage protruding forward</li><li>Body leaning to one side</li><li>A visibly curved spine when bending forward</li></ul>', '<ul><li><strong>Idiopathic</strong> — most cases; cause unknown, cannot be prevented</li><li><strong>Neuromuscular conditions</strong> — cerebral palsy, muscular dystrophy, spinal muscular atrophy, spina bifida</li><li><strong>Birth defects</strong> — abnormal spinal development in the womb</li><li><strong>Injury or infection</strong> of the spine, and spinal cord abnormalities</li></ul>', '<p>Treatment depends on age, curve severity and likelihood of progression. Mild curves need observation only; bracing is used for growing children with curves of 25–40 degrees, worn 15–23 hours a day (successfully stops progression in 80% of children). Surgery is reserved for curves greater than 40 degrees.</p><h3>How physiotherapy helps</h3><p>Scoliosis can be managed effectively with physiotherapy. Our physiotherapists focus on strengthening the muscles that support your spine, correcting posture, and prescribing specific exercises depending on whether your case is mild, moderate or severe — reducing pain and limiting curve progression.</p>', '/images/back-p.jpg', 8, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `treatments` (`id`, `slug`, `name`, `category`, `summary`, `symptoms_html`, `causes_html`, `treatment_html`, `banner_image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (9, 'bell-palsy', 'Physiotherapy for Bell''s Palsy', 'Neurological Rehabilitation', 'Bell''s palsy causes sudden paralysis or weakness on one side of the face — the most common cause of facial paralysis. Early physiotherapy with electrical stimulation and facial exercises significantly improves recovery.', '<ul><li>Sudden weakness or paralysis on one side of the face</li><li>Drooping eyebrow and mouth corner</li><li>Difficulty closing one eyelid, causing eye dryness</li><li>Excessive tears in one eye</li><li>Drooling from one side of the mouth</li><li>Pain around the jaw and behind the ear</li><li>Facial pain or abnormal sensations</li></ul>', '<ul><li>Inflammation and swelling of cranial nerve VII (the facial nerve)</li><li><strong>Dormant viral infections</strong> — herpes simplex, varicella (chickenpox)</li><li><strong>Impaired immunity</strong> — stress, sleep deprivation, minor illness, autoimmune syndromes</li><li><strong>Lyme disease</strong> and other facial-nerve inflammations</li><li><strong>Myelin sheath damage</strong> — the fatty insulation around nerve fibres</li><li><strong>Risk factors</strong> — pregnancy, preeclampsia, obesity, hypertension, diabetes and recurring infections</li></ul>', '<p>Bell''s palsy results from a problem in cranial nerve VII, which connects the brain to the muscles of facial expression. Most patients recover — and physiotherapy meaningfully improves the speed and completeness of that recovery.</p><h3>Physiotherapy treatment</h3><ul><li><strong>Electric stimulation</strong> — 30 contractions to maintain muscle tone</li><li><strong>Galvanic stimulation</strong> — for the muscles of the face</li><li><strong>Faradic stimulation</strong> — for the nerve trunk</li><li><strong>Facial exercises</strong> — practiced regularly to retrain expression</li></ul><h3>Advice for recovery</h3><ul><li>Apply moist heat to paralysed areas to reduce pain; massage gently</li><li>Keep the face warm — exposure to cold can aggravate paralysis</li><li>Keep the eye moist: close it manually with a finger, tape it for sleeping, use protective glasses in the shower</li><li>Eat a balanced diet rich in leafy greens; Vitamin B12, B6 and zinc support nerve growth</li><li>Manage stress with relaxation exercises; cut food small and chew on the comfortable side</li></ul>', '/images/bell-palsy.jpg', 9, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
INSERT INTO `doctors` (`id`, `slug`, `name`, `designation`, `qualification`, `experience_years`, `bio_html`, `photo_url`, `phone`, `email`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'doctor-neelam-sharma', 'Doctor Neelam Sharma', 'Senior Consultant Physiotherapist & Clinical Director', 'B.P.T, M.P.T (Neuro), MIAP', 12, '<h3 class="icon-default"><a href="doctor-neelam-sharma.html">Dr. Neelam Sharma</a></h3>\n                <h5 class="icon-primary"><strong> MPT(Neuro), BPT, MIAP</strong></h5>\n                <p>Dr. Neelam Sharma, B.P.T., M.P.Th, M.I.A.P. has done specialization in Physiotherapy. Dr. Neelam\n                    Sharma is best Physiotherapist in orthopaedic, Neurological, Geriatrics, Pediatrics conditions. She is\n                    managing her clinic with modern and advanced treatment to help you move well and stay happy and\n                    well trained team which is working under guidance of her.</p>\n                <p>She provides best Physiotherapy service in Noida like Manual Therapy, Exercise therapy, Modalities (\n                    US,IFT,TENS LASER,SWD,MS,MH), tapping, Chiropractor, Dry needling, dry cupping, hijama cupping.\n                    Dr. Neelam Sharma is well educated in her field and she is Best Physiotherapist in Noida</p>     \n                 <h3><strong>FAQ</strong></h3>\n                <p>\n               <strong> Q: Where does Dr. Neelam Sharma (Physiotherapist) practice?</strong><br>\n               Ans - Dr. Neelam Sharma(PT) practices at K R Physiotherapy &amp; Rehabilitation Clinic, Kisan Tower Basement, Main Road Hoshiyarpur, Sector 51 Noida, Uttar Pradesh 201301. She also provides home visits.<br></p>\n               <p>\n               <strong> Q: How can I take Dr. Neelam Sharma (Physiotherapist)\'s appointment ?</strong><br>\n               Ans - You can take Dr. Neelam Sharma’s appointment through website or you can call on 85953 21652.<br></p>\n               <p>\n               <strong> Q: Why do patients visit Dr. Neelam Sharma (Physiotherapist)?</strong><br>\n               Ans - Patients frequntly visit Dr. Neelam Sharma(PT) for neck pain, back pain, knee pain, all orthro and neurological problems. She also provides dry needling, cupping therapy, chirapractic and other manual therapies.<br></p>\n               <p>\n               <strong> Q: What is Dr. Neelam Sharma (Physiotherapist)\'s education qualification?</strong><br>\n               Ans - Dr. Neelam Sharma(PT) has following qualifications- BPT ( Bachelor of Physiotherapy), MPT (Master of Physiotherapy)(Neurology).<br></p>\n               <p>\n               <strong> Q: What is physiotherapy treatment cost?</strong><br>\n                </p>', '/images/Dr-Neelam-Sharma2.jpg', '+91 8595321652', 'info@krphysiotherapy.com', 1, 'published', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
