INSERT INTO `seo_metadata` (`id`, `entity_type`, `entity_id`, `path`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `robots`, `og_title`, `og_description`, `og_image`, `og_url`, `structured_data_json`, `created_at`, `updated_at`) VALUES (22, 'treatment', 7, '/cerebral-palsy.html', 'Physiotherapy for Cerebral Palsy in Noida', '', 'Physiotherapy for Cerebral Palsy in Noida, Cerebral Palsy Physiotherapy, Cerebral Palsy Physiotherapy in Noida ', 'cerebral-palsy.html', 'INDEX,FOLLOW', 'Physiotherapy for Cerebral Palsy in Noida - Cerebral Palsy Physiotherapy', 'KR Physiotherapy is an expert in physiotherapy for the prevention, rehabilitation and recovery of orthopaedic, neurological and sports-related conditions. ', 'http://krphysiotherapy.com/images/favicon.png', 'http://www.krphysiotherapy.com/cerebral-palsy.html', '["{\\n  \\"@context\\": \\"https://schema.org\\",\\n  \\"image\\":\\"https://www.krphysiotherapy.com/images/logo1.jpg\\",\\n  \\"@type\\": \\"LocalBusiness\\",\\n  \\"address\\": {\\n    \\"@type\\": \\"PostalAddress\\",\\n    \\"streetAddress\\": \\"Kisan Tower, Basement, Main Road Hosiyarpur, Sector 51\\",\\n    \\"addressLocality\\": \\"Noida\\",\\n    \\"addressRegion\\": \\"Uttar Pradesh\\",\\n    \\"postalCode\\": \\"201304\\",\\n    \\"addressCountry\\": \\"India\\"\\n  },\\n  \\n  \\"aggregateRating\\": {\\n    \\"@type\\": \\"AggregateRating\\",\\n    \\"ratingValue\\": \\"5\\",\\n    \\"reviewCount\\": \\"219\\"\\n  },\\n  \\"name\\": \\"KR Physiotherapy & Rehabilitation Clinic (Physiotherapist, Physiotherapy at Home, Physiotherapy Clinic in Noida)\\",\\n  \\"description\\": \\"KR Physiotherapy is a physiotherapy clinic in Noida, offers physiotherapy services with the help of the best physiotherapist. Our physiotherapy clinic is nearby sector 50 and sector 53 in Noida.\\",\\n  \\"openingHours\\": [\\n\\"Monday\\t8.30am–8.30pm\\",\\n\\"Tuesday 8.30am–8.30pm\\",\\n\\"Wednesday 8.30am–8.30pm\\",\\n\\"Thursday 8.30am–8.30pm\\",\\n\\"Friday\\t8.30am–8.30pm\\",\\n\\"Saturday 8.30am–8.30pm\\",\\n\\"Sunday\\t8.30am–8.30pm\\"\\n  ],\\n  \\"priceRange\\": \\"INR\\",\\n  \\n  \\"telephone\\": \\" +91 8595321652, +91 7668527335\\",\\n  \\"url\\": \\"https://www.krphysiotherapy.com/\\"\\n}",{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is the cause of cerebral palsy?","acceptedAnswer":{"@type":"Answer","text":"Cerebral palsy is caused by the abnormal development of the brain and can happen during pregnancy, birth, and early infancy. In many cases, the cause is not clear."}},{"@type":"Question","name":"What are the symptoms of cerebral palsy?","acceptedAnswer":{"@type":"Answer","text":"The most common symptoms are delayed milestones like difficulty sitting, standing, and walking; tightening of muscles; in coordination and balance problems; and increased reflexes."}},{"@type":"Question","name":"How is cerebral palsy diagnosed?","acceptedAnswer":{"@type":"Answer","text":"CP symptoms, such as difficulty rolling, sitting, and standing, are usually visible after a few months to a year after birth. In some cases where symptoms are mild, diagnosis may be delayed longer. A series of tests is conducted to diagnose cerebral palsy. These tests are MRIs, cranial ultrasounds, CT scans, and some laboratory tests."}},{"@type":"Question","name":"Is CP contagious?","acceptedAnswer":{"@type":"Answer","text":"No, CP is not contagious."}},{"@type":"Question","name":"Can cerebral palsy be cured?","acceptedAnswer":{"@type":"Answer","text":"CP is not curable, but physiotherapy is helping a lot with muscle function and improving the quality of a child’s life."}},{"@type":"Question","name":"Does cerebral palsy get worse?","acceptedAnswer":{"@type":"Answer","text":"It is a non-progressive disorder, so it will never get worse."}},{"@type":"Question","name":"Can cerebral palsy be treated?","acceptedAnswer":{"@type":"Answer","text":"Yes, physiotherapy treatment for cerebral palsy is really helpful because it focuses on function, movement, and maintaining and improving the child’s abilities."}},{"@type":"Question","name":"What treatments are available for cerebral palsy?","acceptedAnswer":{"@type":"Answer","text":"There are several types of treatment approaches available for cerebral palsy, depending on how severe the symptoms are. Therapies include physiotherapy, occupational therapy, speech therapy, and orthosis devices."}},{"@type":"Question","name":"Which types of therapy are useful for cerebral palsy?","acceptedAnswer":{"@type":"Answer","text":"Physiotherapy is most important for treating cerebral palsy after diagnosis. In physiotherapy, we apply some major techniques for maintaining and improving muscle functions, balance, and coordination."}},{"@type":"Question","name":"Can my child goes to school along with continuing therapy session?","acceptedAnswer":{"@type":"Answer","text":"Yes, a child can attend school while receiving physiotherapy sessions."}}]}]', '2026-09-12 11:45:44', '2026-09-12 11:45:44');
